import { quote } from './quote.mjs';
import { help } from './help.mjs';
if (process.argv[2] === '--help') {
  console.log(help);
} else {
  try {
    console.log(JSON.stringify(quote(JSON.parse(process.argv[2]))));
  } catch (error) {
    console.error(error.message);
    process.exitCode = 2;
  }
}
